"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
export default function CardsFolder() {
    const root = useRef<HTMLElement>(null);
    const inView = useInView(root, { once: true, amount: 0.2 });
    const reduce = useReducedMotion();
    const [hovered, setHovered] = useState(false);
    const active = hovered && !reduce;
    return (<>
      <>
        <motion.article ref={root} initial={{ opacity: 0, y: 14 }} animate={inView ? { opacity: 1, y: 0 } : { opacity: 0, y: 14 }} transition={reduce ? { duration: 0 } : { duration: 0.5, ease: ARTEMIS_EASE_OUT }} onHoverStart={() => setHovered(true)} onHoverEnd={() => setHovered(false)} className="art:relative art:aspect-[1.06/1] art:w-full art:max-w-md art:isolate art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background">
          <div aria-hidden="true" className="art:absolute art:inset-px art:overflow-hidden art:rounded-sm">
            <motion.div animate={{ scale: active ? 1.035 : 1 }} transition={ARTEMIS_SPRING_PANEL} aria-hidden="true" className="art:absolute art:-inset-2 art:overflow-hidden art:bg-[linear-gradient(128deg,#e9b071_0%,#d96b4e_42%,#347d78_100%)]">
              <div className="art:absolute art:-top-12 art:left-[8%] art:h-48 art:w-20 art:rotate-[24deg] art:rounded-full art:bg-white/25 art:blur-xl"/>
              <div className="art:absolute art:top-4 art:left-[38%] art:h-40 art:w-16 art:-rotate-[18deg] art:rounded-full art:bg-white/20 art:blur-lg"/>
              <div className="art:absolute art:-right-12 art:-bottom-10 art:size-52 art:rounded-full art:border-[30px] art:border-white/15"/>
            </motion.div>
          </div>
          <div className="art:absolute art:top-[9%] art:right-[6%] art:z-10 art:max-w-[42%] art:rounded-full art:border art:border-border art:bg-background/85 art:px-3 art:py-2 art:text-right art:font-medium art:text-foreground art:text-xs art:leading-4 art:backdrop-blur-sm">
            {"Workspace collection"}
          </div>
          <motion.div animate={{ y: active ? -2 : 0 }} transition={ARTEMIS_SPRING_PANEL} aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:top-0 art:bottom-[-2px] art:z-10">
            <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none" className="art:size-full">
              <path d="M 0 100 V 35 C 0 30.5 2.8 28 7 28 H 38 C 41.5 28 43.5 29.2 46 31.8 L 52.5 38.2 C 54.6 40.2 57 41 61 41 H 94 C 98 41 100 43.4 100 47.5 V 100 Z" className="art:fill-background"/>
            </svg>
          </motion.div>
          <motion.div animate={{ y: active ? -2 : 0 }} transition={ARTEMIS_SPRING_PANEL} className="art:pointer-events-none art:absolute art:inset-0 art:z-20">
            <div className="art:absolute art:top-[32.5%] art:left-[5%] art:max-w-[48%]">
              <h2 className="art:truncate art:text-foreground art:leading-tight art:tracking-[-0.025em] art:text-4xl art:font-medium">
                {"Daily memo"}
              </h2>
              <p className="art:mt-1 art:truncate art:text-muted-foreground art:text-sm art:@min-[640px]/artemis:text-base">
                {"Notes & journaling"}
              </p>
            </div>
            <div className="art:absolute art:right-[6%] art:bottom-[6%] art:left-[5%] art:flex art:items-end art:justify-between art:gap-6">
              <div className="art:flex art:min-w-0 art:items-baseline art:gap-2">
                <span className="art:font-medium art:text-4xl art:text-foreground art:leading-none art:tracking-[-0.05em] art:tabular-nums art:@min-[640px]/artemis:text-5xl">
                  {"05"}
                </span>
                <span className="art:text-foreground art:text-sm art:@min-[640px]/artemis:text-base">
                  {"Docs"}
                </span>
              </div>
              <span className="art:truncate art:text-right art:font-medium art:text-foreground art:text-sm art:tabular-nums art:@min-[640px]/artemis:text-base">
                {"1,270 notes"}
              </span>
            </div>
          </motion.div>
        </motion.article>
      </>
    </>);
}
